#!/usr/bin/env python3
import os
import sys
import hashlib
import argparse
from concurrent.futures import ThreadPoolExecutor

def calculate_sha256(file_path):
    """Calcula el hash SHA-256 de un archivo en bloques para optimizar memoria."""
    sha256_hash = hashlib.sha256()
    try:
        with open(file_path, "rb") as f:
            for byte_block in iter(lambda: f.read(65536), b""):
                sha256_hash.update(byte_block)
        return file_path, sha256_hash.hexdigest(), None
    except Exception as e:
        return file_path, None, str(e)

def generate_hashes(target_dir, output_file):
    print(f"🔒 Iniciando Generación Criptográfica de Hashes SHA-256 (Cadena de Custodia)")
    print(f"📁 Directorio objetivo: {target_dir}")

    pdf_files = []
    for root, dirs, files in os.walk(target_dir):
        for f in files:
            if f.lower().endswith('.pdf'):
                pdf_files.append(os.path.join(root, f))

    total = len(pdf_files)
    print(f"📊 Total de archivos a firmar: {total}")

    processed = 0
    with open(output_file, "w", encoding="utf-8") as out_f, ThreadPoolExecutor(max_workers=16) as executor:
        out_f.write("# REGISTRO CRIPTOGRÁFICO SHA-256 - CADENA DE CUSTODIA FORENSE\n")
        out_f.write(f"# Total de Archivos: {total}\n")
        out_f.write("# Formato: HASH_SHA256  RUTA_RELATIVA\n\n")

        for file_path, sha256, err in executor.map(calculate_sha256, pdf_files):
            processed += 1
            if sha256:
                rel_path = os.path.relpath(file_path, target_dir)
                out_f.write(f"{sha256}  {rel_path}\n")
            if processed % 5000 == 0 or processed == total:
                print(f"  ➜ Procesados {processed} / {total} archivos ({(processed/total*100):.1f}%)...")

    print(f"✅ Hashes SHA-256 generados exitosamente.")
    print(f"📄 Manifiesto de Cadena de Custodia guardado en: {output_file}")

if __name__ == "__main__":
    parser = argparse.ArgumentParser(description="Generador Criptográfico de Hashes SHA-256 para Cadena de Custodia")
    parser.add_argument("--dir", type=str, default="/media/andrea-zabala-c/D A T A1/segundaVuelta/claveros_pdf", help="Directorio objetivo")
    parser.add_argument("--out", type=str, default="/media/andrea-zabala-c/D A T A1/segundaVuelta/claveros_pdf/firmas_criptograficas_sha256.txt", help="Archivo de manifiesto de salida")
    args = parser.parse_args()

    generate_hashes(args.dir, args.out)

#!/usr/bin/env python3
import os
import sys
import hashlib
import argparse
from concurrent.futures import ThreadPoolExecutor

def calculate_sha256(file_path):
    sha256_hash = hashlib.sha256()
    try:
        with open(file_path, "rb") as f:
            for byte_block in iter(lambda: f.read(65536), b""):
                sha256_hash.update(byte_block)
        return file_path, sha256_hash.hexdigest()
    except Exception:
        return file_path, None

def scan_pdf_hashes(directory):
    pdf_map = {}
    files_to_process = []
    for root, dirs, files in os.walk(directory):
        for f in files:
            if f.lower().endswith('.pdf'):
                full_path = os.path.join(root, f)
                files_to_process.append((f, full_path))

    with ThreadPoolExecutor(max_workers=16) as executor:
        for (filename, full_path), (p, sha) in zip(files_to_process, executor.map(lambda x: calculate_sha256(x[1]), files_to_process)):
            if sha:
                # Se indexa por nombre de archivo normalizado o identificador E14
                pdf_map[filename] = (full_path, sha)
    return pdf_map

def compare_collections(new_dir, old_dirs, output_report):
    print("🔍 Escaneando y calculando hashes de la NUEVA descarga masiva...")
    new_map = scan_pdf_hashes(new_dir)
    print(f"✅ Nueva descarga cargada: {len(new_map)} archivos PDF.")

    print("\n🔍 Escaneando y calculando hashes de las colecciones ANTERIORES...")
    old_map = {}
    for od in old_dirs:
        if os.path.exists(od):
            print(f"  ➜ Procesando carpeta previa: {od}")
            m = scan_pdf_hashes(od)
            old_map.update(m)

    print(f"✅ Colecciones previas cargadas: {len(old_map)} archivos PDF únicos.")

    identicos = []
    modificados = []
    solo_nuevos = []

    for filename, (new_path, new_sha) in new_map.items():
        if filename in old_map:
            old_path, old_sha = old_map[filename]
            if new_sha == old_sha:
                identicos.append((filename, new_sha))
            else:
                modificados.append((filename, old_sha, new_sha, old_path, new_path))
        else:
            solo_nuevos.append((filename, new_sha))

    print("\n================ RESULTADOS COMPARATIVOS DE HASHES ================")
    print(f"Total en Nueva Descarga: {len(new_map)}")
    print(f"Total Coincidentes Evaluados: {len(identicos) + len(modificados)}")
    print(f"🟢 Archivos Idénticos (Sin cambios de hash): {len(identicos)}")
    print(f"🚨 Archivos Modificados / Alterados (Diferencia de Hash): {len(modificados)}")
    print(f"🆕 Archivos Nuevos Adicionados: {len(solo_nuevos)}")

    with open(output_report, "w", encoding="utf-8") as out:
        out.write("# REPORTE PERICIAL COMPARATIVO DE HASHES SHA-256\n")
        out.write(f"# Total evaluados: {len(new_map)}\n")
        out.write(f"# Idénticos: {len(identicos)} | Modificados: {len(modificados)} | Nuevos: {len(solo_nuevos)}\n\n")

        if modificados:
            out.write("## 🚨 ARCHIVOS CON HASH ALTERADO / MODIFICADO\n")
            out.write("NOMBRE_ARCHIVO | HASH_ANTERIOR | HASH_NUEVO\n")
            out.write("-" * 80 + "\n")
            for fn, o_sha, n_sha, o_p, n_p in modificados:
                out.write(f"{fn} | {o_sha} | {n_sha}\n")
            out.write("\n")

        out.write("## 🟢 MUESTRA DE ARCHIVOS IDÉNTICOS\n")
        for fn, sha in identicos[:100]:
            out.write(f"{fn} | {sha}\n")

    print(f"\n📄 Reporte comparativo pericial guardado en: {output_report}")

if __name__ == "__main__":
    new_directory = "/media/andrea-zabala-c/D A T A1/segundaVuelta/claveros_pdf"
    previous_directories = [
        "/home/andrea-zabala-c/Desktop/actas",
        "/home/andrea-zabala-c/Documents/Para Revisar/E14",
        "/media/andrea-zabala-c/D A T A1/EVIDENCIA_FORENSE_E14_2026",
        "/media/andrea-zabala-c/BACKUP/EVIDENCIA_FORENSE_E14_2026"
    ]
    report_path = "/home/andrea-zabala-c/Desktop/REPORTE_COMPARATIVO_HASHES_E14.md"
    compare_collections(new_directory, previous_directories, report_path)

