                    with z.open(file_info) as f:
                        reader = csv.reader(TextIOWrapper(f, "utf-8"))
                        next(reader) # skip header
                        for row in reader:
                            if len(row) > 1:
                                date = row[1].split()[0]
                                dates.add(date)
    except Exception:
        pass
print(sorted(list(dates)))
